-- ============================================================
-- COHORT A FULL RUN — backfill recipes for 3,556 legacy shades
-- Generated: 2026-05-27
-- Total INSERTs: 4034
-- Sampling numbers: 3556 (10 already imported in dry-run)
-- ============================================================

-- Step 1: Patch the 1 wrong-null-pack row from the dry-run
-- (1322115/IN28209272 should be 1L per broader pack rules)
UPDATE sampling_recipes
SET "packCode" = '1L'::"PackCode"
WHERE "samplingNo" = '1322115' AND "skuCode" = 'IN28209272';

-- Step 2: Insert 4,034 new recipes


-- Step 3: Mark first recipe per sampling number as primary
-- (Skips the 10 dry-run sampling numbers since those already have isPrimary set)
WITH first_per_sno AS (
  SELECT DISTINCT ON ("samplingNo") "samplingNo", id
  FROM sampling_recipes
  WHERE "samplingNo" NOT IN ('134591', '106', '132331', '10995', '1323979', '120', '132523', '13', '1322115', '1323957')
    AND "samplingNo" NOT LIKE '26-%'
  ORDER BY "samplingNo", id ASC
)
UPDATE sampling_recipes sr
SET "isPrimary" = true
FROM first_per_sno fps
WHERE sr.id = fps.id;

-- Step 4: Link existing tinting history (usage_log) to new recipes
UPDATE sampling_usage_log ul
SET "recipeId" = sr.id
FROM sampling_recipes sr
WHERE ul."recipeId" IS NULL
  AND ul."samplingNo" = sr."samplingNo"
  AND UPPER(TRIM(ul."skuCodeRaw")) = UPPER(TRIM(sr."skuCode"));

-- Step 5: Final verification queries

-- 5a. Recipe row count (should be old count + 4034)
SELECT COUNT(*) AS total_recipes FROM sampling_recipes;

-- 5b. Cohort A shades that now have recipes (should be 3,566)
SELECT COUNT(DISTINCT "samplingNo") AS legacy_shades_with_recipes
FROM sampling_recipes
WHERE "samplingNo" NOT LIKE '26-%';

-- 5c. usage_log link rate (should be near 100%)
SELECT
  COUNT(*) AS total_usage_rows,
  COUNT("recipeId") AS linked_to_recipe,
  ROUND(100.0 * COUNT("recipeId") / COUNT(*), 1) AS link_pct
FROM sampling_usage_log
WHERE "samplingNo" NOT LIKE '26-%';

-- 5d. Spot check a few random sampling numbers
SELECT "samplingNo", COUNT(*) AS recipes, 
       SUM(CASE WHEN "isPrimary" THEN 1 ELSE 0 END) AS primary_count
FROM sampling_recipes
WHERE "samplingNo" NOT LIKE '26-%'
GROUP BY "samplingNo"
HAVING SUM(CASE WHEN "isPrimary" THEN 1 ELSE 0 END) != 1
LIMIT 20;
-- Expected: 0 rows (every sno should have exactly 1 isPrimary=true)